#![cfg(test)]
#![allow(clippy::approx_constant)]

use super::telemetry::Telemetry;

fn sample() -> Telemetry {
    let mut s = Telemetry::default();
    s.set_device_id(3000000000);
    s.set_timestamp_us(12000000000);
    s.set_mode(5);
    s.set_status(5);
    s.set_armed(1);
    s.set_callsign(b"skywire");
    s.set_battery_mv(60000);
    s
}

#[test]
fn round_trip() {
    let msg = sample();
    let wire = msg.serialize();
    assert_eq!(wire.len(), msg.size());
    assert_eq!(wire.len(), Telemetry::SIZE);
    let got = Telemetry::from_bytes(&wire).unwrap();
    assert!(got.equals(&msg));
    assert_eq!(got, msg);
}

#[test]
fn short_buffer() {
    let mut got = sample();
    let zeros = vec![0u8; Telemetry::SIZE - 1];
    let err = got.deserialize(&zeros).unwrap_err();
    assert_eq!(err.kind(), std::io::ErrorKind::UnexpectedEof);
    assert_eq!(got, sample());
    assert!(Telemetry::from_bytes(&[]).is_err());
}

#[test]
fn serialize_into_appends() {
    let msg = sample();
    let mut out = vec![0xee];
    msg.serialize_into(&mut out);
    assert_eq!(out[0], 0xee);
    assert_eq!(out[1..], msg.serialize()[..]);
}

#[test]
fn deserialize_ignores_trailing_bytes() {
    let msg = sample();
    let mut wire = msg.serialize();
    wire.push(0xee);
    assert_eq!(Telemetry::from_bytes(&wire).unwrap(), msg);
}

#[test]
fn bitfield_setters() {
    let mut s = Telemetry::default();
    s.set_mode(0x15);
    assert_eq!(s.mode(), 5);
    s.set_status(0xd);
    assert_eq!(s.status(), 5);
    s.set_armed(0x3);
    assert_eq!(s.armed(), 1);
}

#[test]
fn string_setters() {
    let mut s = Telemetry::default();
    s.set_callsign(&[b'x'; 8 + 1]);
    assert_eq!(s.callsign(), &[b'x'; 8]);
    s.set_callsign(b"y");
    assert_eq!(s.callsign()[0], b'y');
    assert!(s.callsign()[1..].iter().all(|&b| b == 0));
}

