fn json() {
    let msg = sample();
    let text = msg.to_json();
    let got = Telemetry::from_json(&text).unwrap();
    assert_eq!(got, msg);
    assert_eq!(got.to_json(), text);
    assert_eq!(Telemetry::from_json(text.as_bytes()).unwrap(), msg);
}

